import sys

def min_moves_to_divisible_by_25(n):
    str_n = str(n)
    length = len(str_n)

    # Check for '00' at the end
    if '00' in str_n:
        index = str_n.rfind('00')
        if index == length - 2:
            return 0
        else:
            return length - 2 - index

    # Check for '25', '50', '75' at the end
    valid_endings = ['25', '50', '75']
    for ending in valid_endings:
        if ending in str_n:
            index = str_n.rfind(ending)
            if index == length - 2:
                return 0
            else:
                # Count the number of leading zeros if we move this ending to the end
                leading_zeros = str_n[:index].count('0')
                if leading_zeros > 0:
                    return -1
                return length - 2 - index

    return -1

